    {
      "text": "For filing an application, the Manual identifies regulations 4.1 (approved form), 4.2 (filing requirements) and 4.3 (representation of trade marks).",
      "quotes": [
        {
          "ref": "TMM/Part2/1/trade-mark-regulations-1995",
          "quote": "Regulation 4.1 Applications - approved form Regulation 4.2 Applications in approved form - requirements for filing Regulation 4.3 Representation of trade marks"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For general document-filing requirements, the Manual identifies regulations 21.1 to 21.5.",
      "quotes": [
        {
          "ref": "TMM/Part2/1/trade-mark-regulations-1995",
          "quote": "Regulation 21.1 Compliance with instruction on approved forms Regulation 21.2 Requirements for filing documents"
